import{_ as t,o,c as a,a5 as s}from"./chunks/framework.CsGesDJn.js";const g=JSON.parse('{"title":"Sequence Flow — Remove Agency","description":"","frontmatter":{},"headers":[],"relativePath":"feature/agency-workspace/3-4-6-remove-agency/sequence-flow.md","filePath":"feature/agency-workspace/3-4-6-remove-agency/sequence-flow.md"}'),r={name:"feature/agency-workspace/3-4-6-remove-agency/sequence-flow.md"};function n(i,e,c,d,l,h){return o(),a("div",null,[...e[0]||(e[0]=[s('<h1 id="sequence-flow-—-remove-agency" tabindex="-1">Sequence Flow — Remove Agency <a class="header-anchor" href="#sequence-flow-—-remove-agency" aria-label="Permalink to &quot;Sequence Flow — Remove Agency&quot;">​</a></h1><p>&gt; Companion to <code>spec.md</code> (FR 3.4.6). This file lists each actor → action → system step in enough detail to draw the sequence diagram directly. Business explanation lives in <code>spec.md</code>. &gt; &gt; Updated 2026-09-23, matching the system as built today.</p><h2 id="actors" tabindex="-1">Actors <a class="header-anchor" href="#actors" aria-label="Permalink to &quot;Actors&quot;">​</a></h2><ul><li><strong>Owner</strong></li><li><strong>Client</strong> — the BrandHub web application.</li><li><strong>System</strong> — the BrandHub service.</li><li><strong>Database</strong> — PostgreSQL (<code>agencies</code>, <code>workspaces</code>).</li></ul><hr><h2 id="flow-a-—-remove-an-agency-cascading-to-its-workspaces" tabindex="-1">Flow A — Remove an Agency (cascading to its Workspaces) <a class="header-anchor" href="#flow-a-—-remove-an-agency-cascading-to-its-workspaces" aria-label="Permalink to &quot;Flow A — Remove an Agency (cascading to its Workspaces)&quot;">​</a></h2><ol><li>Owner → Client: selects Remove in the Agency settings → a two-step confirmation dialog asks the Owner to type the Agency name and states the consequences, including that the Workspaces of the Agency are affected.</li><li>Client → System: submits the removal (<code>DELETE /api/v1/agencies/{agencyId}</code>).</li><li>System — remove: a. Loads the Agency by its identifier — not found → <code>404 AGENCY_NOT_FOUND</code>. b. Confirms the caller is the Owner of the Agency — otherwise <code>403 NOT_AGENCY_OWNER</code>. c. Marks the Agency SOFT_DELETED with the current time. d. Cascades: loads every Workspace belonging to the Agency and marks each one SOFT_DELETED with the same removal time.</li><li>System → Client: no data, the removal is done.</li><li>Client: shows a confirmation and takes the user back to the Agency list.</li></ol><h2 id="flow-b-—-restore-an-agency-within-30-days-cascading-to-its-workspaces" tabindex="-1">Flow B — Restore an Agency (within 30 days, cascading to its Workspaces) <a class="header-anchor" href="#flow-b-—-restore-an-agency-within-30-days-cascading-to-its-workspaces" aria-label="Permalink to &quot;Flow B — Restore an Agency (within 30 days, cascading to its Workspaces)&quot;">​</a></h2><ol><li>Owner → Client: opens the removed Agencies or follows a direct link, and selects Restore.</li><li>Client → System: submits the restore (<code>POST /api/v1/agencies/{agencyId}/restore</code>).</li><li>System — restore: a. Loads the Agency by its identifier — not found → <code>404 AGENCY_NOT_FOUND</code>. b. Confirms the caller is the Owner of the Agency — otherwise <code>403 NOT_AGENCY_OWNER</code>. c. Confirms the Agency is currently SOFT_DELETED — otherwise <code>400 AGENCY_NOT_DELETED</code>. d. Confirms a removal time is recorded and that no more than 30 days have passed since it — otherwise <code>410 RESTORE_WINDOW_EXPIRED</code>. e. Marks the Agency ACTIVE, clears its removal time and refreshes its update timestamp. f. Cascades: loads every Workspace belonging to the Agency and marks ACTIVE, with the removal time cleared and the update timestamp refreshed, only those Workspaces whose removal time matches the removal batch of the Agency. A Workspace whose removal time differs — because it was removed on its own beforehand — is left untouched.</li><li>System → Client: the Agency profile with the status ACTIVE.</li><li>Client: shows a confirmation and refreshes the screen.</li></ol><hr><h2 id="error-paths" tabindex="-1">Error paths <a class="header-anchor" href="#error-paths" aria-label="Permalink to &quot;Error paths&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Step</th><th>Failure condition</th><th>HTTP</th><th>Error code</th></tr></thead><tbody><tr><td>Remove</td><td>Agency does not exist</td><td>404</td><td><code>AGENCY_NOT_FOUND</code></td></tr><tr><td>Remove</td><td>Caller is not the Owner</td><td>403</td><td><code>NOT_AGENCY_OWNER</code></td></tr><tr><td>Restore</td><td>Agency does not exist</td><td>404</td><td><code>AGENCY_NOT_FOUND</code></td></tr><tr><td>Restore</td><td>Caller is not the Owner</td><td>403</td><td><code>NOT_AGENCY_OWNER</code></td></tr><tr><td>Restore</td><td>Agency was never removed</td><td>400</td><td><code>AGENCY_NOT_DELETED</code></td></tr><tr><td>Restore</td><td>More than 30 days have passed since the removal</td><td>410</td><td><code>RESTORE_WINDOW_EXPIRED</code></td></tr></tbody></table><h2 id="notes" tabindex="-1">Notes <a class="header-anchor" href="#notes" aria-label="Permalink to &quot;Notes&quot;">​</a></h2><ul><li><strong>Correction applied:</strong> an earlier revision recorded that the removal and the restore acted on the Agency alone, with no effect on its Workspaces. That no longer holds. The removal marks every Workspace of the Agency SOFT_DELETED with the same removal time, and the restore marks ACTIVE again the Workspaces whose removal time matches the removal batch.</li><li>Remaining risk, by design rather than a defect: a Workspace that had already been removed on its own beforehand is recognised by its different removal time and is not brought back when the Agency is restored. Workspaces removed together with the Agency do come back.</li></ul>',14)])])}const y=t(r,[["render",n]]);export{g as __pageData,y as default};
